window.GEME_IMG={"accovacciato": "data:image/png;base64,", "aterra": "data:image/png;base64,", "bicchiere": "data:image/png;base64,", "calcio": "data:image/png;base64,", "camminata1": "data:image/png;base64,", "camminata2": "data:image/png;base64,", "caricapugno": "data:image/png;base64,", "colpito": "data:image/png;base64,", "cratere": "data:image/png;base64,", "f1a": "data:image/png;base64,", "f1b": "data:image/png;base64,", "fendente": "data:image/png;base64,", "fumo": "data:image/png;base64,", "guardia": "data:image/png;base64,", "incudine": "data:image/png;base64,", "incudine2": "data:image/png;base64,", "ko": "data:image/png;base64,", "lancio": "data:image/png;base64,", "montante": "data:image/png;base64,", "onda": "data:image/png;base64,", "onda_urto": "data:image/png;base64,", "parata": "data:image/png;base64,", "pozza": "data:image/png;base64,", "presa": "data:image/png;base64,", "provocazione": "data:image/png;base64,", "pugno": "data:image/png;base64,", "rialzo": "data:image/png;base64,", "ritratto": "data:image/png;base64,", "salto": "data:image/png;base64,", "sconfitta": "data:image/png;base64,", "sfera": "data:image/png;base64,", "sgambetto": "data:image/png;base64,", "stordito": "data:image/png;base64,", "super1": "data:image/png;base64,", "tifo": "data:image/png;base64,", "vittoria": "data:image/png;base64,", "vittoria2": "data:image/png;base64,"};window.GEME_SCR={"CUOVE": "data:image/png;base64,", "NEGVONI": "data:image/png;base64,", "PIT_STOP": "data:image/png;base64,", "POVCA_TVOIA": "data:image/png;base64,", "SBADABAM": "data:image/png;base64,", "TI_DISTVUGGO": "data:image/png;base64,"};window.GEME_SRC="\nQUOTES.geme={intro:[\"Ti mangio il cuoVe.\",\"NegVoni senza ghiaccio. Per te.\",\"Ti distVuggo.\",\"PoVca tVoia, cominciamo.\"],win:[\"Ti ho mangiato il cuoVe.\",\"NegVoni senza ghiaccio. Offvo io.\",\"Ti ho distVutto.\",\"PoVca tVoia, che pVestazione.\"],lose:[\"PoVca tVoia...\",\"AndVe... vendicami.\",\"Il NegVoni eVa annacquato.\"]};\nCOUPLE.geme=COUPLE.geme||{}; COUPLE.geme.stefano={intro:[\"SDB, ti mangio il cuoVe. Con paVcella.\"],win:[\"NegVoni senza ghiaccio. Paghi tu.\"],lose:[\"PoVca tVoia... vincono sempVe i penalisti.\"]};\nCOUPLE.stefano=COUPLE.stefano||{}; COUPLE.stefano.geme={intro:[\"Geme, il contratto non ti salva.\"],win:[\"Clausola di placcaggio: nulla.\"],lose:[\"Va bene, il Negroni lo offro io.\"]};\nCOUPLE.geme.cugi={intro:[\"Cugi, mischia chiusa. Ti distVuggo.\"],win:[\"Meta. E NegVoni.\"],lose:[\"PoVca tVoia, Cugi...\"]};\nCOUPLE.cugi=COUPLE.cugi||{}; COUPLE.cugi.geme={intro:[\"Geme, lascia il Negroni e placca.\"],win:[\"Placcato in giacca e cravatta.\"],lose:[\"Va bene, offro io.\"]};\nCOUPLE.geme.allibrator={intro:[\"Allibratore, quota su di me?\"],win:[\"Quota pagata. NegVoni per tutti.\"],lose:[\"PoVca tVoia, era una quota tVuccata.\"]};\nCOUPLE.allibrator=COUPLE.allibrator||{}; COUPLE.allibrator.geme={intro:[\"Geme, ti do a 10.\"],win:[\"Schedina vincente.\"],lose:[\"Mai scommettere contro un rugbista.\"]};\nCOUPLE.geme.ciuppa={intro:[\"Ciuppa, teVzo tempo dopo. PVima ti distVuggo.\"],win:[\"Il NegVoni batte la biVVa.\"],lose:[\"PoVca tVoia, che placcaggio.\"]};\nCOUPLE.ciuppa=COUPLE.ciuppa||{}; COUPLE.ciuppa.geme={intro:[\"Geme, birra o Negroni?\"],win:[\"Birra. Sempre birra.\"],lose:[\"Negroni senza ghiaccio... ok, hai vinto.\"]};\nif(SPRITES.geme){ const N=SPRITES.geme; N.guardia2=N.guardia; N.paratabassa=N.accovacciato; N.entrata=N.provocazione; N.lancio2=N.lancio; N.caricacalcio=N.caricapugno; N.sguardo=N.provocazione; N.turbo=N.pugno; N.sfondamento=N.pugno; N.stordita=N.stordito; N.super2=N.super1; N.esulta1=N.vittoria; N.esulta2=N.tifo; N.esulta3=N.vittoria; N.volo=N.ko; N.svenuto0=N.aterra; N.vittoria3=N.vittoria2; }\n/* GEME1 - base: Negroni lanciato (distanza), Cascata di Negroni (speciale), super \"Pit stop\" (monoposto che investe).\n   Evoluzione EVIL GEME: fendente di fuoco (distanza), telecinesi (speciale), super \"Incudine\" (telecinesi che tira giu' un'incudine). */\nfunction gemeImg(n){ const D=window.GEME_IMG||{}, c=SPRITES.__gImg=SPRITES.__gImg||{}; if(!D[n]) return null; if(!c[n]){ const i=new Image(); i.src=D[n]; c[n]=i; } return c[n].complete&&c[n].width?c[n]:null; }\nfunction drawGemeProj(p){ let im, s=1, rot=0;\n  if(p.kind==='negroni'){ im=gemeImg('bicchiere'); s=0.42; rot=(G.frame%40)/40*Math.PI*2*(p.vx<0?-1:1); }\n  else if(p.kind==='fendente'){ im=gemeImg('fendente'); s=0.62; }\n  else if(p.gcasc){ return true; }\n  else if(p.gtele){ im=gemeImg('sfera'); s=0.55*(0.9+0.1*Math.sin(G.frame*0.5)); }\n  if(!im) return false; ctx.save(); ctx.translate(p.x,p.y); ctx.scale(p.vx<0?-1:1,1); if(rot) ctx.rotate(rot); ctx.imageSmoothingEnabled=false; ctx.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s); ctx.restore(); return true; }\nconst GEMESU={dmg:17,dmgE:18,alto:70,vel:24,rng:95}; try{ setTimeout(()=>['bicchiere','onda','pozza','f1a','f1b','fumo','incudine','incudine2','fendente','sfera','cratere','onda_urto'].forEach(gemeImg),0); }catch(e){}\nfunction callGeme(f,o){ const evil=f.def.lv>=2;\n  if(evil){ f.gsup={t:0,evil:1,tgt:o,hx:o?o.x:f.x+f.facing*200}; floatText('TI DISTVUGGO!',f.x,f.y-270,'#ff2a2a',24,60); try{ tone('sawtooth',90,40,.7,.12); }catch(e){} }\n  else { const dir=f.facing||1; f.gsup={t:0,onda:1,dir:dir,x:f.x-dir*60,tgt:o,hit:0}; floatText('NEGVONI!',f.x,f.y-270,'#ff3a2a',30,60); G.shake=Math.max(G.shake||0,10); try{ tone('sawtooth',80,300,.8,.1); }catch(e){} } } /*GEMESUPER1*/\nfunction stepGeme(f,o){ if(f.gwave){ const Wv=f.gwave; Wv.x+=Wv.dir*11; Wv.t++; if(Wv.t%3===0) FX.push({x:Wv.x+Wv.dir*60,y:GROUND-200-rnd()*120,vx:Wv.dir*(2+rnd()*3),vy:-2-rnd()*3,life:22,c:rnd()<.5?'#e0402a':'#ff8a3a'}); if(Wv.t>120) f.gwave=null; } /*GEMEONDA1*/ const M=f.gsup; if(!M) return; M.t++; const t=o||M.tgt;\n  if(M.onda){ if(M.t<10) return; M.x+=M.dir*12; if(M.t%2===0) FX.push({x:M.x+M.dir*90,y:GROUND-260-rnd()*160,vx:M.dir*(2+rnd()*4),vy:-3-rnd()*3,life:24,c:rnd()<.5?'#e0402a':'#ff8a3a'}); if(M.t%4===0) G.shake=Math.max(G.shake||0,5);\n    if(t&&!M.hit&&t.state!=='ko'&&Math.abs(t.x-M.x)<120){ M.hit=1; G.shake=Math.max(G.shake,18); hit(f,t,GEMESU.dmg,14,46,{sup:true,heavy:true,launch:true,dirx:M.dir,y:t.y-60}); if(t.state==='hit') floatText('SPLASH!',t.x,t.y-240,'#ff8a1a',32,60); }\n    if(M.t>130) f.gsup=null; return; } /*GEMESUPER1*/\n  if(M.evil){ if(t&&M.t<26) M.hx+=Math.max(-8,Math.min(8,t.x-M.hx));\n    if(M.t===40){ G.shake=Math.max(G.shake,22); M.crT=0; if(t&&Math.abs(t.x-M.hx)<GEMESU.rng&&t.state!=='ko'){ hit(f,t,GEMESU.dmgE,14,46,{sup:true,heavy:true,launch:true,air:true,dirx:t.x>=M.hx?1:-1,y:t.y-60}); if(t.state==='hit') floatText('SBADABAM!',t.x,t.y-230,'#ff2a2a',32,60); } else floatText('POVCA TVOIA!',f.x,f.y-250,'#ff2a2a',20,50); }\n    if(M.crT!=null) M.crT++; if(M.crT!=null&&M.crT>46) f.gsup=null; return; }\n  if(M.t<14) return; M.cx+=M.dir*GEMESU.vel; if(M.t%3===0) G.shake=Math.max(G.shake||0,3);\n  if(t&&!M.hit&&t.state!=='ko'&&Math.abs(t.x-M.cx)<80){ M.hit=1; if(t.y>GROUND-GEMESU.alto){ G.shake=Math.max(G.shake,16); hit(f,t,GEMESU.dmg,14,46,{sup:true,low:true,heavy:true,launch:true,dirx:M.dir,y:t.y-60}); if(t.state==='hit') floatText('SORPASSO!',t.x,t.y-230,'#ffffff',30,60); } else M.salto=1; }\n  if(M.cx*M.dir>(M.dir>0?W+400:400)){ f.gsup=null; } }\nfunction drawGeme(F){ if(!F||!F.def||F.def.spriteKey!=='geme') return; if(F.gwave){ const Wv=F.gwave, on=gemeImg('onda'); if(on){ const s=2.4, w=on.width*s, h=on.height*s, bob=Math.sin(Wv.t*0.4)*6; ctx.save(); ctx.imageSmoothingEnabled=false; ctx.globalAlpha=Math.min(1,(120-Wv.t)/20); ctx.translate(Wv.x,GROUND+14+bob); ctx.scale(Wv.dir,1); ctx.drawImage(on,-w/2,-h,w,h); ctx.restore(); } } /*GEMEONDA1*/ const M=F.gsup; if(!M) return; ctx.save(); ctx.imageSmoothingEnabled=false;\n  if(M.onda){ const on=gemeImg('onda'); if(on&&M.t>=10){ const s=3.4, w=on.width*s, h=on.height*s, bob=Math.sin(M.t*0.35)*8; ctx.globalAlpha=Math.min(1,(130-M.t)/20); ctx.translate(M.x,GROUND+20+bob); ctx.scale(M.dir,1); ctx.drawImage(on,-w/2,-h,w,h); } ctx.restore(); return; } /*GEMESUPER1*/\n  if(!M.evil){ if(M.t<14){ ctx.restore(); return; } const car=gemeImg((M.t>>2)%2?'f1b':'f1a')||gemeImg('f1a'); const fu=gemeImg('fumo');\n    if(fu){ for(let i=1;i<=3;i++){ const s=0.7*(1+i*0.2); ctx.globalAlpha=0.5/i; ctx.drawImage(fu,M.cx-M.dir*(150+i*60)-fu.width*s/2,GROUND-fu.height*s,fu.width*s,fu.height*s); } ctx.globalAlpha=1; }\n    if(car){ const s=1.05; ctx.translate(M.cx,GROUND+4); ctx.scale(M.dir,1); ctx.drawImage(car,-car.width*s/2,-car.height*s,car.width*s,car.height*s); }\n    ctx.restore(); return; }\n  if(M.t<40){ const k=Math.min(1,M.t/40), y=-160+(GROUND-40+160)*k*k; const an=gemeImg('incudine2')||gemeImg('incudine'); if(an){ const s=0.85; ctx.drawImage(an,M.hx-an.width*s/2,y-an.height*s,an.width*s,an.height*s); } }\n  else { const an=gemeImg('incudine'), cr=gemeImg('cratere'), ou=gemeImg('onda_urto'), c=M.crT||0;\n    if(cr){ const s=1; ctx.drawImage(cr,M.hx-cr.width*s/2,GROUND+8-cr.height*s,cr.width*s,cr.height*s); }\n    if(ou&&c<20){ const s=0.6+c*0.06; ctx.globalAlpha=1-c/20; ctx.drawImage(ou,M.hx-ou.width*s/2,GROUND-ou.height*s/2,ou.width*s,ou.height*s); ctx.globalAlpha=1; }\n    if(an){ const s=0.85; ctx.globalAlpha=Math.max(0,1-c/46); ctx.drawImage(an,M.hx-an.width*s/2,GROUND+4-an.height*s,an.width*s,an.height*s); ctx.globalAlpha=1; } }\n  ctx.restore(); }\n";